"""Galería visual de las mallas que usa el POV; no mide dificultad ni FPS."""
from pathlib import Path
import sys,base64,json
sys.path.insert(0,str(Path(__file__).resolve().parent))
from browser_server import local_server
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1]
with local_server(R) as url,sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader','--enable-webgl'])
 p=b.new_page(viewport={'width':1440,'height':900});errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
 p.add_init_script("addEventListener('load',()=>{SceneTransitions.enabled=false;SceneTransitions.finish();});")
 p.goto(url);p.click('#bNew');p.evaluate("Game.loop=()=>{};FirstPerson.setEnabled(true);Game.render()")
 data=p.evaluate('''()=>{const T=THREE,renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setSize(390,470);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;const cv=document.createElement('canvas');cv.width=1560;cv.height=1608;const c=cv.getContext('2d');c.fillStyle='#101b21';c.fillRect(0,0,cv.width,cv.height);c.fillStyle='#cfdbd5';c.font='24px sans-serif';c.fillText('RIUTEX 2 / PERSONAJES 3D / TEXTURAS DE PÍXEL',24,34);const types=['sonambulo','enfermera','carnicero','cl_blind','wx_spitter','wx_scuttler','cl_hound','cl_moth','cl_regent','lf_wren','ds_matriarch','squad'];for(let i=0;i<types.length;i++){const type=types[i],scene=new T.Scene();scene.background=new T.Color('#17262d');scene.add(new T.HemisphereLight('#dbe6e0','#26343b',2));const light=new T.DirectionalLight('#ffe5c4',3);light.position.set(-55,90,70);scene.add(light);const rim=new T.DirectionalLight('#7fabc2',1.2);rim.position.set(55,50,-45);scene.add(rim);const root=type==='squad'?POV3DAssets.ally({name:'Rojas',col:'#44554c'},Game):POV3DAssets.enemy({id:1,type,def:ENEMY_TYPES[type]||{},phase:1},Game);scene.add(root);POV3DAssets.animateEnemy(root,{x:0,y:0,mode:'idle'},Game,1,.016);const bounds=new T.Box3().setFromObject(root),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3()),camera=new T.PerspectiveCamera(35,390/470,.1,500),radius=size.length()/2,distance=radius/Math.sin(35*Math.PI/360)*1.05;camera.position.copy(center).add(new T.Vector3(.28,.16,1).normalize().multiplyScalar(distance));camera.lookAt(center);renderer.render(scene,camera);const x=(i%4)*390,y=55+Math.floor(i/4)*517;c.drawImage(renderer.domElement,x,y);c.fillStyle='#cedbd4';c.font='18px sans-serif';c.fillText(type==='squad'?'Escuadrón / Rojas':type==='carnicero'?'El Carnicero':ENEMY_TYPES[type]?.name||type,x+18,y+490);}const output=cv.toDataURL();renderer.dispose();return output;}''')
 (R/'artifacts/characters-v0210.png').write_bytes(base64.b64decode(data.split(',',1)[1]))
 p.evaluate("Hospital.toHospital(Game);Game.story.restrained=false;Hospital.inject(Game);Hospital.lobbyReached(Game);Game.story.seq='free';Game.state='play';UI.screen(null);Game.player.x=44.5*32;Game.player.y=29.5*32;Game.player.angle=0;Game.player.hurtFlash=Game.player.poison=0;Game.keys={};Game.carn.dormant=false;Game.carn.x=Game.player.x+120;Game.carn.y=Game.player.y;Game.carn.face=Math.PI;Game.enemies=[Game.carn];Game.inv.items=[];Game.player.weapon=null;Game.giveWeapon('pistol',12,true);Game.update(0);FirstPerson.pitch=0;Game.render();UI.hud(Game.player,Game.inv,Game.mut)")
 p.screenshot(path='artifacts/character-gameplay-v0210.png')
